/* 1. Rewrite the three .session-card rules above as one nested rule. */
/* 2. Hide sold-out cards when #hide-full is checked. */
/* 3. Give a card a #6d28d9 border when its .save box is checked. */

solution.css:
.session-card {
  margin-block-end: 12px;
  padding: 12px 16px;
  border: 2px solid #e5e7eb;
  border-radius: 12px;

  h2 {
    margin: 0 0 8px;
    font-size: 1.05rem;
  }

  &:hover {
    background: #faf5ff;
  }

  &:has(.save:checked) {
    border-color: #6d28d9;
  }
}

.badge-full {
  display: inline-block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
  background: #fee2e2;
  color: #991b1b;
}

.schedule:has(#hide-full:checked) .session-card:has(.badge-full) {
  display: none;
}
